contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry driving the property check
    function run(uint amount, address receiver) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // We only consider the case where the owner (this contract) calls and the receiver is this contract.
        // The function must hold for all inputs, so allow any values but we will focus the assertion on the case receiver==address(this).

        // record balances before the call
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        // perform the call and detect revert
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General rule (one assert):
        // When the owner (this contract) calls sendTo with receiver == address(this):
        //   - if the call succeeds then amount>0 and receiver!=address(0) and c's balance decreases by amount and this contract's balance increases by amount;
        //   - if the call reverts then there is no observable transfer between c and this contract (balances unchanged).
        // For other receiver values the assertion does not constrain behavior.
        assert(
            receiver == address(this)
            ? (
                !reverted
                ? (amount > 0 && receiver != address(0) && balC_before == balC_after + amount && balThis_after == balThis_before + amount)
                : (balC_before == balC_after && balThis_before == balThis_after)
              )
            : true
        );
    }

    receive() external payable { }
}

